import { test, expect as baseExpect } from "@playwright/test";
import { mkdir, mkdtemp, readFile, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { createHash } from "node:crypto";
import { configuration, createService, startServer } from "../../server.mjs";

const expect = baseExpect.configure({ timeout: 120000 });
let service, server, workspace, run, original;
const hash = value => createHash("sha256").update(value).digest("hex");
test.beforeAll(async () => {
  if (!process.env.NIXTLA_E2E_OUTPUT) throw new Error("Set NIXTLA_E2E_OUTPUT to a disposable session artifact directory.");
  await mkdir(process.env.NIXTLA_E2E_OUTPUT, { recursive: true });
  workspace = await mkdtemp(join(resolve(process.env.NIXTLA_E2E_OUTPUT), "calendar-"));
  const input = join(workspace, "synthetic-run");
  await mkdir(join(input, "appendix"), { recursive: true });
  await writeFile(join(input, "manifest.json"), JSON.stringify({ spec: { horizon: 2, freq: "MS" } }));
  await writeFile(join(input, "forecast.csv"), "unique_id,ds,yhat\n001,2024-03-01,4000\n001,2024-04-01,4200\n");
  await writeFile(join(input, "appendix", "history.csv"), "unique_id,ds,y\n001,2024-01-01,3100\n001,2024-02-01,2900\n");
  original = hash(await readFile(join(input, "forecast.csv")));
  const { runtime, contract } = await configuration();
  service = createService({ workspace, python: runtime.python, contract });
  await service.call("initialize");
  run = await service.call("import_run", { path: input, name: "Synthetic calendar fixture" });
  const catalog = await service.call("catalog");
  await service.call("save_state", { expectedRevision: catalog.revision, state: {
    documents: [{ id: "calendar", runId: run.id, title: "Synthetic monthly flow · calendar review", series: "001", view: "Diagnostics", analysis: { section: "Seasonality" } }],
    activeId: "calendar", theme: "light",
  } });
  server = await startServer({ workspace, service });
});
test.afterAll(async () => { await server?.close(); await service?.close(); });

test("calendar counts, exclusive holidays, assumption persistence and immutable scenario export", async ({ page }) => {
  test.setTimeout(600000);
  const errors = [], jobs = [];
  page.on("pageerror", error => errors.push(error.message));
  page.on("request", request => { if (request.url().endsWith("/api") && request.postDataJSON()?.operation === "start_job") jobs.push(request.postDataJSON()); });
  await page.goto(server.url);
  const panel = page.getByRole("region", { name: "Calendar adjustment", exact: true });
  const update = panel.getByRole("button", { name: "Update calendar preview", exact: true });
  await expect(panel.getByRole("region", { name: "Calendar day counts", exact: true }).locator("tbody tr")).toHaveCount(2);
  await panel.getByRole("button", { name: "Values", exact: true }).click();
  await expect(panel.getByRole("region", { name: "Calendar scenario values", exact: true })).toContainText("3,100.00");
  await expect(panel.getByRole("region", { name: "Calendar scenario values", exact: true })).toContainText("4,000.00");
  await page.getByLabel("Display units", { exact: true }).selectOption("thousands");
  await expect(panel.getByRole("region", { name: "Calendar scenario values", exact: true })).toContainText("3.10");
  await expect(panel.getByRole("region", { name: "Calendar scenario values", exact: true })).toContainText("4.00");
  await page.getByLabel("Display units", { exact: true }).selectOption("raw");
  await panel.getByLabel("Weekend relative weight").fill("0.5");
  await expect(panel.getByRole("button", { name: "Export calendar & assumptions", exact: true })).toBeDisabled();
  await update.click();
  await expect(panel.getByRole("region", { name: "Calendar scenario values", exact: true })).toContainText("3,016.00");
  await panel.getByLabel("Holiday calendar", { exact: true }).selectOption("custom");
  await panel.getByLabel("Custom holiday dates").fill("2024-03-02\n2024-03-02\n2024-03-04");
  await panel.getByLabel("Holiday relative weight").fill("0.25");
  await update.click();
  await expect(panel.getByRole("region", { name: "Calendar scenario values", exact: true })).toContainText("2,900.00");
  await panel.getByRole("button", { name: "Days & holidays", exact: true }).click();
  const counts = panel.getByRole("region", { name: "Calendar day counts", exact: true });
  await expect(counts.locator("tbody tr").first()).toContainText("25.00");
  await panel.getByText("Holiday dates & coverage · 2 dates", { exact: true }).click();
  await expect(panel.getByRole("region", { name: "Applied holiday calendar", exact: true }).locator("tbody tr")).toHaveCount(2);
  await panel.getByRole("button", { name: "Factor bridge", exact: true }).click();
  await expect(panel.getByRole("region", { name: "Calendar factor bridge", exact: true }).locator("tbody tr")).toHaveCount(2);
  await expect(panel.getByRole("region", { name: "Calendar factor bridge", exact: true })).toContainText("1.000000");
  await panel.getByText("Normalized history & method", { exact: true }).click();
  await expect(panel).toContainText("even when the comparison month has no holidays");
  await expect(panel.getByRole("region", { name: "Calendar-normalized actuals", exact: true }).locator("tbody tr")).toHaveCount(2);
  await panel.getByRole("button", { name: "Export calendar & assumptions", exact: true }).click();
  const receipt = panel.getByRole("region", { name: "Calendar export receipt", exact: true });
  await expect(receipt).toContainText("4 rows");
  const [csvFile] = await Promise.all([page.waitForEvent("download"), receipt.getByRole("button", { name: "Download calendar CSV", exact: true }).click()]);
  const csv = await readFile(await csvFile.path(), "utf8");
  expect(csv.trim().split(/\r?\n/)).toHaveLength(5);
  expect(csv).toContain("calendar_scenario");
  const [jsonFile] = await Promise.all([page.waitForEvent("download"), receipt.getByRole("button", { name: "Download assumptions JSON", exact: true }).click()]);
  const recipe = JSON.parse(await readFile(await jsonFile.path(), "utf8"));
  expect(recipe.recipe.settings.weekendWeight).toBe(0.5);
  expect(recipe.recipe.settings.holidayWeight).toBe(0.25);
  expect(recipe.holidayDates).toHaveLength(2);
  expect(recipe.forecastChanged).toBe(false);
  await expect(page.locator(".save-state")).toContainText("Saved");
  await page.reload();
  await expect(panel.getByLabel("Weekend relative weight")).toHaveValue("0.5");
  await expect(panel.getByRole("region", { name: "Calendar day counts", exact: true }).locator("tbody tr")).toHaveCount(2);
  await panel.getByLabel("Holiday relative weight").fill("");
  await expect(update).toBeDisabled();
  await expect(panel.getByRole("alert")).toContainText("Blank or invalid");
  await panel.getByRole("button", { name: "Reset to equal days", exact: true }).click();
  await expect(panel.getByLabel("Holiday relative weight")).toHaveValue("1");
  await expect(panel.getByLabel("Weekend relative weight")).toHaveValue("1");
  await update.click();
  await expect(panel.getByRole("region", { name: "Calendar day counts", exact: true }).locator("tbody tr")).toHaveCount(2);
  await panel.getByLabel("Holiday calendar", { exact: true }).selectOption("us_federal");
  await panel.getByLabel("Weekend relative weight").fill("0.5");
  await panel.getByLabel("Holiday relative weight").fill("0.2");
  await update.click();
  await expect(panel.getByRole("button", { name: "Export calendar & assumptions", exact: true })).toBeEnabled();
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await page.locator(".document-body").evaluate(element => { element.scrollTop = 0; });
    await page.screenshot({ path: join(workspace, "calendar-desktop.png") });
    await panel.getByRole("region", { name: "Saved forecast vs calendar-only scenario", exact: true }).screenshot({ path: join(workspace, "calendar-comparison.png") });
    await counts.scrollIntoViewIfNeeded();
    await page.screenshot({ path: join(workspace, "calendar-details.png") });
    await panel.getByRole("button", { name: "Factor bridge", exact: true }).click();
    await panel.getByRole("region", { name: "Calendar factor bridge", exact: true }).scrollIntoViewIfNeeded();
    await page.screenshot({ path: join(workspace, "calendar-factors.png") });
    await panel.getByText("Normalized history & method", { exact: true }).click();
    await panel.locator("details").first().locator(".footnote").screenshot({ path: join(workspace, "calendar-method.png") });
    await panel.getByText("Normalized history & method", { exact: true }).click();
    await panel.getByRole("button", { name: "Days & holidays", exact: true }).click();
  }
  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByRole("button", { name: "Toggle library", exact: true }).click();
  await page.getByLabel("Appearance").selectOption("dark");
  await page.locator(".document-body").evaluate(element => { element.scrollTop = 0; });
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") await page.screenshot({ path: join(workspace, "calendar-mobile-dark.png") });
  if (process.env.NIXTLA_E2E_CAPTURE !== "0") {
    await panel.locator(".section-heading").first().evaluate(element => element.scrollIntoView({ block: "start" }));
    await page.screenshot({ path: join(workspace, "calendar-mobile-controls.png") });
    await counts.scrollIntoViewIfNeeded();
    await page.screenshot({ path: join(workspace, "calendar-mobile-results.png") });
  }
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await panel.getByLabel("Calendar periods").selectOption("all");
  await expect(counts.locator("tbody tr")).toHaveCount(4);
  await panel.getByLabel("Holiday calendar", { exact: true }).selectOption("custom");
  await panel.getByLabel("Custom holiday dates").fill("2024-02-30");
  await update.click();
  await expect(panel.getByRole("alert")).toContainText("Invalid holiday date");
  await panel.getByRole("button", { name: "Reset to equal days", exact: true }).click();
  await update.click();
  await expect(panel.getByRole("button", { name: "Export calendar & assumptions", exact: true })).toBeEnabled();
  expect(errors).toEqual([]);
  expect(jobs).toEqual([]);
  expect(hash(await readFile(join(workspace, ".nixtla-workbench", "versions", run.id, "forecast.csv")))).toBe(original);
  expect((await service.call("catalog")).jobs).toEqual([]);
  console.log(`Calendar artifacts: ${workspace}`);
});
